<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import IconButton from './IconButton.vue';
const emit=defineEmits(['notice']);
const text={sample:'Sub-Store 日志 · 全部为示例，不读取真实后端',keyword:'搜索日志',ignoreCase:'忽略大小写',regex:'正则表达式',limit:'显示条数（0 为全部）',auto:'自动刷新示例',interval:'刷新间隔（秒）',level:'级别',refresh:'刷新示例日志',select:'选择日志',exit:'退出选择',clear:'清空示例日志',clearQuestion:'确认清空这些示例日志？不会清除真实后端。',cancel:'取消',confirm:'确认清空',copy:'复制这条日志',copySelected:'复制选中日志',all:'全选当前结果',unselect:'取消全选',empty:'没有匹配的日志',badRegex:'正则表达式无效，请检查后重试',copied:'已复制示例日志',copyFailed:'浏览器未允许复制，请选择日志文字复制',cleared:'已清空示例日志；真实后端未变更',time:'时间',message:'消息',tags:'标签',noCache:'日志缓存关闭时，需在缓存设置中将最大日志条数改为大于 0。真实可用性需连接后端验证。'};
const make=(id,level,message,tags=[])=>({id,time:new Date(Date.now()-Math.max(0,8-id)*12000).toISOString(),level,message,tags});
const logs=ref([make(1,'info','[示例] Sub-Store 已准备就绪',['服务']),make(2,'info','[示例] 开始读取订阅',['订阅']),make(3,'warn','[示例] 某个远程来源返回空节点，按配置继续处理',['订阅','来源']),make(4,'info','[示例] 节点重命名完成',['操作']),make(5,'error','[示例] 演示脚本错误：未执行真实脚本',['文件','预览']),make(6,'info','[示例] 文件预览完成',['文件']),make(7,'debug','[示例] 命中示例缓存',['缓存'])]);
const keyword=ref('');const ignoreCase=ref(true);const regex=ref(false);const limit=ref(100);const autoRefresh=ref(false);const interval=ref(5);const level=ref('all');const selectionMode=ref(false);const selected=ref([]);const confirmClear=ref(false);const refreshing=ref(false);let timer;let sequence=8;
const regexError=computed(()=>{if(!regex.value||!keyword.value)return '';try{new RegExp(keyword.value,ignoreCase.value?'i':'');return ''}catch{return text.badRegex}});
const shown=computed(()=>{if(regexError.value)return [];let rows=logs.value.filter(log=>{if(level.value!=='all'&&log.level!==level.value)return false;const haystack=[log.time,log.level,log.message,...log.tags].join(' ');if(!keyword.value)return true;return regex.value?new RegExp(keyword.value,ignoreCase.value?'i':'').test(haystack):ignoreCase.value?haystack.toLowerCase().includes(keyword.value.toLowerCase()):haystack.includes(keyword.value)});const max=Math.max(0,Number(limit.value)||0);return max?rows.slice(-max):rows});
const allSelected=computed(()=>shown.value.length>0&&shown.value.every(log=>selected.value.includes(log.id)));
const selectedRows=computed(()=>logs.value.filter(log=>selected.value.includes(log.id)));
function toggle(id){selected.value=selected.value.includes(id)?selected.value.filter(i=>i!==id):[...selected.value,id]}
function toggleAll(){const ids=shown.value.map(log=>log.id);selected.value=allSelected.value?selected.value.filter(id=>!ids.includes(id)):[...new Set([...selected.value,...ids])]}
function format(log){return `${log.time} [${log.level.toUpperCase()}] ${log.tags.map(t=>'#'+t).join(' ')} ${log.message}`}
async function copy(rows){try{await navigator.clipboard.writeText(rows.map(format).join('\n'));emit('notice',text.copied)}catch{emit('notice',text.copyFailed)}}
function refresh(automatic=false){refreshing.value=true;const id=sequence++;logs.value.push(make(id,'info',automatic?'[示例] 定时刷新演示，无后端请求':'[示例] 手动刷新演示，无后端请求',['刷新']));if(logs.value.length>200)logs.value=logs.value.slice(-200);refreshing.value=false;if(!automatic)emit('notice','已刷新示例日志，没有请求后端')}
function clear(){logs.value=[];selected.value=[];confirmClear.value=false;emit('notice',text.cleared)}
watch([autoRefresh,interval],()=>{clearInterval(timer);if(autoRefresh.value)timer=setInterval(()=>refresh(true),Math.max(1,Number(interval.value)||5)*1000)});
onBeforeUnmount(()=>clearInterval(timer));
</script>
<template>
 <section class="complete-logs" aria-label="Sub-Store 日志">
  <div class="logs-topbar"><p class="logs-example">{{ text.sample }}</p><div class="logs-icons"><IconButton :label="text.refresh" icon="faArrowRotateRight" :disabled="refreshing" @activate="refresh(false)" /><IconButton :label="selectionMode?text.exit:text.select" :icon="selectionMode?'faXmark':'faLayerGroup'" :disabled="!logs.length" @activate="selectionMode=!selectionMode" /><IconButton :label="text.clear" icon="faTrashCan" :disabled="!logs.length" danger @activate="confirmClear=true" /></div></div>
  <div class="logs-filters"><FormKit type="search" v-model="keyword" :label="text.keyword" placeholder="按时间、消息或标签筛选" /><FormKit type="select" v-model="level" :label="text.level" :options="{all:'全部级别',debug:'DEBUG',info:'INFO',warn:'WARN',error:'ERROR'}" /><div class="logs-search-flags"><FormKit type="checkbox" v-model="ignoreCase" :label="text.ignoreCase" /><FormKit type="checkbox" v-model="regex" :label="text.regex" /></div><FormKit type="number" v-model="limit" :label="text.limit" min="0" step="1" validation="min:0" /><div class="logs-search-flags"><FormKit type="checkbox" v-model="autoRefresh" :label="text.auto" /></div><FormKit v-if="autoRefresh" type="number" v-model="interval" :label="text.interval" min="1" step="1" validation="min:1" /></div>
  <p v-if="regexError" class="logs-error" role="alert">{{ regexError }}</p>
  <section v-if="confirmClear" class="logs-confirm"><p>{{ text.clearQuestion }}</p><div><button class="button" @click="confirmClear=false">{{ text.cancel }}</button><button class="button danger-button" @click="clear">{{ text.confirm }}</button></div></section>
  <div class="logs-summary" aria-live="polite"><span>显示 {{ shown.length }} / {{ logs.length }} 条示例日志</span><span v-if="autoRefresh">每 {{ Math.max(1,Number(interval)||5) }} 秒刷新</span></div>
  <div v-if="selectionMode" class="logs-selection"><button class="button" :disabled="!shown.length" @click="toggleAll">{{ allSelected?text.unselect:text.all }}</button><span>已选 {{ selectedRows.length }} 条</span><button class="button primary" :disabled="!selectedRows.length" @click="copy(selectedRows)">{{ text.copySelected }}</button></div>
  <p v-if="!shown.length" class="logs-empty">{{ text.empty }}</p>
  <div v-else class="logs-entries"><article v-for="log in shown" :key="log.id" class="logs-entry" :class="['level-'+log.level,{'is-selected':selected.includes(log.id)}]"><FormKit v-if="selectionMode" type="checkbox" :model-value="selected.includes(log.id)" :label="'选择 '+log.message" outer-class="log-check" @input="value=>value!==selected.includes(log.id)&&toggle(log.id)" /><div class="log-body"><div class="log-metadata"><time :datetime="log.time">{{ new Date(log.time).toLocaleString('zh-CN') }}</time><span class="log-level">{{ log.level.toUpperCase() }}</span></div><p>{{ log.message }}</p><div class="log-tags"><button v-for="tag in log.tags" :key="tag" @click="keyword=tag">#{{ tag }}</button></div></div><IconButton :label="text.copy" icon="faClone" @activate="copy([log])" /></article></div>
  <details class="logs-help"><summary>日志不可用时怎么办</summary><p>{{ text.noCache }}</p><p>原版日志还依赖后端版本。可在代理 App 控制台、容器日志、Android 终端或后端运行环境查看真实输出；此原型不伪造后端连接状态。</p></details>
 </section>
</template>
<style scoped>
.complete-logs{min-width:0}.logs-topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:20px}.logs-example{font-size:12px;color:var(--muted);margin:0;line-height:1.8}.logs-icons{display:flex;flex-shrink:0}.logs-filters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 16px;border-bottom:1px solid var(--line);padding-bottom:16px}.logs-search-flags{display:flex;align-items:center;flex-wrap:wrap;gap:12px}.logs-filters :deep(.formkit-outer){margin-bottom:4px}.logs-filters :deep(.formkit-label){font-size:12px}.logs-filters :deep(.formkit-input:not([type=checkbox])){font-size:16px;min-height:44px;width:100%}.logs-error{color:var(--danger);font-size:13px}.logs-confirm{background:var(--bg);border:1px solid var(--danger);padding:16px;border-radius:12px;margin:16px 0}.logs-confirm p{font-size:13px}.logs-confirm>div{display:flex;gap:8px;justify-content:flex-end}.logs-summary{font-size:12px;color:var(--muted);display:flex;justify-content:space-between;gap:12px;margin:16px 0}.logs-selection{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:16px}.logs-selection>span{font-size:12px;color:var(--muted);margin-right:auto}.logs-selection .button{font-size:12px;padding:10px 12px}.logs-entry{display:flex;align-items:flex-start;gap:12px;padding:16px 0;border-bottom:1px solid var(--line)}.logs-entry.is-selected{background:var(--accent-soft);border-radius:10px;padding:16px 12px}.log-body{flex:1;min-width:0}.log-metadata{display:flex;gap:12px;align-items:center;font-size:11px;color:var(--muted);flex-wrap:wrap}.log-level{color:var(--accent);font-size:10px;font-weight:600}.level-error .log-level{color:var(--danger)}.level-warn .log-level{color:var(--text)}.log-body>p{font:12px/1.8 ui-monospace,monospace;margin:8px 0;white-space:pre-wrap;overflow-wrap:anywhere}.log-tags{display:flex;flex-wrap:wrap;gap:8px}.log-tags button{font-size:11px;background:var(--bg);border:1px solid var(--line);color:var(--muted);border-radius:6px;min-height:32px;padding:4px 8px}.logs-entry :deep(.log-check){flex:0 0 24px;margin-top:2px}.logs-entry :deep(.log-check .formkit-label){position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.logs-entry :deep(.log-check .formkit-input){min-width:20px;min-height:20px}.logs-empty{padding:48px 16px;background:var(--bg);border-radius:12px;text-align:center;color:var(--muted);font-size:13px}.logs-help{margin-top:24px;color:var(--muted);font-size:12px}.logs-help summary{min-height:44px;padding:10px 0;cursor:pointer}.logs-help p{line-height:1.8}@media(max-width:600px){.logs-filters{grid-template-columns:1fr}.logs-topbar{display:block}.logs-icons{justify-content:flex-end;margin-top:12px}.logs-entry{gap:8px}.log-tags button{min-height:44px}.logs-summary{flex-wrap:wrap}}
</style>

<style scoped>
@media(max-width:600px){.logs-entry :deep(.log-check){min-width:44px;min-height:44px;display:flex;align-items:center;justify-content:center}}
</style>
